            () -> Query2.harness(template),
            () -> Query3.harness(template),
            () -> Query4.harness(template),
            () -> Query5.harness(template)
        );

        int idx = 0;
        for (var harness : harnesses) {
            idx += 1;
            System.out.println("Executing query" + idx + "...");
            try {
